#include <stdio.h>
void cal_sum(int arr[],int size,int k)
{
    int p1=0,sum=0;
    for(int i=1;i<=(size-k+1);i++)
    {
        for(int j=p1;j<=(p1+k);j++)
        {
            sum=sum+ arr[j];
        }
        printf("%d",sum);
        printf("\n");
        p1++;
        sum=0;
    }
}
